// Find the error boundary text on the page
const allElements = document.querySelectorAll('*');
const results = [];
for (const el of allElements) {
  if (el.textContent.includes('Something went wrong') && el.children.length < 3) {
    const card = el.closest('[class*="card"], [class*="Card"], [class*="project"], [class*="Project"]');
    results.push({
      errorText: el.textContent.trim().substring(0, 100),
      tagName: el.tagName,
      className: el.className,
      parentCard: card ? { className: card.className, text: card.textContent.trim().substring(0, 200) } : null
    });
  }
}
return JSON.stringify(results, null, 2);

