// Find which project card has the error
const errorDiv = Array.from(document.querySelectorAll('div')).find(el => 
  el.textContent.trim() === 'Something went wrong'
);
if (errorDiv) {
  // Walk up to find the project card context
  let parent = errorDiv.parentElement;
  let context = [];
  while (parent && context.length < 5) {
    context.push({
      tag: parent.tagName,
      class: parent.className,
      textSnippet: parent.textContent.trim().substring(0, 150)
    });
    parent = parent.parentElement;
  }
  // Also look at siblings
  const siblings = errorDiv.parentElement ? Array.from(errorDiv.parentElement.children).map(c => ({
    tag: c.tagName,
    class: c.className,
    text: c.textContent.trim().substring(0, 100)
  })) : [];
  return JSON.stringify({ errorDiv: errorDiv.outerHTML, context, siblings }, null, 2);
}
return 'not found';

