// Try to find the project data in React fiber or window state
// Check if there's any global state or data
const keys = Object.keys(window).filter(k => !k.startsWith('_') && typeof window[k] === 'object' && window[k] !== null);
return JSON.stringify(keys.slice(0, 30));

// Look at all the project cards and their stats to compare
const cards = document.querySelectorAll('div');
const projectCards = [];
for (const card of cards) {
  const text = card.textContent.trim();
  if (text.startsWith('Frontend Redesign') || text.startsWith('API Migration') || 
      text.startsWith('Data Pipeline') || text.startsWith('Mobile App') || 
      text.startsWith('Security Audit') || text.startsWith('Cloud Migration')) {
    if (card.children.length >= 3 && card.children.length <= 6) {
      projectCards.push({
        text: text.substring(0, 200),
        childCount: card.children.length,
        childTexts: Array.from(card.children).map(c => c.textContent.trim().substring(0, 80))
      });
    }
  }
}
return JSON.stringify(projectCards, null, 2);

